import sympy as s, numpy as np, json
from sympy.logic.boolalg import SOPform
spec = TASK["public"]["specification"]
x = s.symbols("x0:10")
f = SOPform(x, [a for a, b in zip(spec["inputs"], spec["outputs"]) if b == 1])
terms = list(f.args) if f.func == s.Or else [f]
mat = {name: W["target."+name].copy() for name in ["w0","b0","w1","b1","w2","b2","w3","b3","out","bias"]}
for a in mat.values():
    a.fill(0)
for k, term in enumerate(terms):
    lits = list(term.args) if term.func == s.And else [term]
    positive = 0
    for lit in lits:
        if lit.func == s.Not:
            mat["w0"][k, x.index(lit.args[0])] = -1
        else:
            mat["w0"][k, x.index(lit)] = 1
            positive += 1
    mat["b0"][k] = 1 - positive
    for layer in (1,2,3):
        mat["w"+str(layer)][k,k] = 1
    mat["out"][1,k] = 1
mat["bias"][0] = 0.5
mat["bias"][2] = -1
patch = []
for name, a in mat.items():
    for idx in np.argwhere(a != 0):
        index = [int(v) for v in idx]
        patch.append({"op":"set","tensor":name,"index":index,"value":float(a[tuple(idx)])})
sub = {"patch":patch}
print(check_submission(sub))
with open("/work/submission.json","w") as fp:
    json.dump(sub,fp)
